import React from 'react';

const PROFILE_ICON_B64 = "data:image/png;base64,";

// Qual aba da coordenadoria o cargo tem
const getCoordTab = cargo => {
  if (['Membro de Marketing','Coordenador de Marketing'].includes(cargo)) return { id:'marketing',  icon:'📢', label:'Marketing' };
  if (['Membro P&P','Coordenador P&P'].includes(cargo))                   return { id:'projetos',   icon:'🔬', label:'P&P'       };
  if (['Membro de Eventos','Coordenador de Eventos'].includes(cargo))     return { id:'eventos',    icon:'🎯', label:'Eventos'   };
  if (['Gestão de Pessoas','Coordenação Geral'].includes(cargo))           return { id:'gestao',     icon:'⚙️', label:'Gestão'    };
  if (cargo === 'Membro de GP')                                            return { id:'gpdemanda',  icon:'👥', label:'Demandas'  };
  return null;
};

const hasChat = cargo => !!getCoordTab(cargo);

export default function BottomNav({ active, onChange, cargo, badgeNotif = 0, badgeChat = 0, badgeChatEventos = 0, badgeChatPP = 0, badgeChatGP = 0, profileIcon = null }) {
  const coordTab = getCoordTab(cargo);

  const tabs = [
    { id:'home',    icon:'⌂',   label:'Home'    },
    ...(coordTab ? [coordTab]                    : []),
    ...(hasChat(cargo) ? [{
      id:    cargo === 'Coordenação Geral'                                        ? 'chat_hub'
           : cargo === 'Membro de Eventos' || cargo === 'Coordenador de Eventos' ? 'chat_eventos'
           : cargo === 'Membro P&P'        || cargo === 'Coordenador P&P'        ? 'chat_pp'
           : cargo === 'Membro de GP'      || cargo === 'Gestão de Pessoas'       ? 'chat_gp' : 'chat',
      icon:  '💬',
      label: 'Chat',
      badge: cargo === 'Coordenação Geral' ? badgeChat + badgeChatEventos + badgeChatPP + badgeChatGP
           : cargo === 'Membro de Eventos' || cargo === 'Coordenador de Eventos' ? badgeChatEventos
           : cargo === 'Membro P&P'        || cargo === 'Coordenador P&P'        ? badgeChatPP
           : cargo === 'Membro de GP'      || cargo === 'Gestão de Pessoas'        ? badgeChatGP : badgeChat,
    }] : []),
    { id:'outros',  icon:'⊞',   label:'Outros', badge: badgeNotif },
    { id:'perfil',  icon:'perfil', label:'Perfil' },
  ];

  return (
    <nav style={{ flexShrink:0, background:'var(--bg2)', borderTop:'1px solid var(--border2)', display:'flex', justifyContent:'space-around', padding:'7px 0', zIndex:100, paddingBottom:'max(10px, env(safe-area-inset-bottom, 10px))' }}>
      {tabs.map(t => {
        const isActive = t.id === active;
        const color = isActive ? 'var(--gold)' : 'var(--muted)';
        return (
          <button key={t.id} onClick={() => onChange(t.id)} aria-label={t.label}
            style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:3, background:'none', border:'none', fontFamily:'var(--font-body)', padding:'0 6px', transition:'color .15s', minWidth:0, flex:1, position:'relative' }}>
            <div style={{ width:40, height:40, borderRadius:11, display:'flex', alignItems:'center', justifyContent:'center', background:isActive?'rgba(201,164,74,.12)':'transparent', border:isActive?'1px solid rgba(201,164,74,.2)':'1px solid transparent', transition:'all .15s', position:'relative' }}>
              {t.icon === 'perfil'
                ? <img src={PROFILE_ICON_B64} alt="Perfil" style={{ width:22, height:22, objectFit:'contain', opacity:isActive?1:0.4 }} />
                : <span style={{ fontSize:20 }}>{t.icon}</span>
              }
              {(t.badge||0) > 0 && (
                <span style={{ position:'absolute', top:-4, right:-4, minWidth:16, height:16, borderRadius:8, background:'#e87f7f', color:'#fff', fontSize:10, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', padding:'0 3px', border:'1.5px solid var(--bg2)' }}>
                  {t.badge > 9 ? '9+' : t.badge}
                </span>
              )}
            </div>
            <span style={{ fontSize:10, fontWeight:isActive?700:500, color, whiteSpace:'nowrap' }}>{t.label}</span>
          </button>
        );
      })}
    </nav>
  );
}
